# Hero Entrance Animation — CSS Scroll-Driven + React

Vou usar **CSS puro com `@keyframes` + `IntersectionObserver`** via hook leve — zero libs externas, ~2KB total.

**Estratégia:**
- `@keyframes` para fade+slide com `cubic-bezier` suave
- Hook `useInView` minimalista (30 linhas, sem deps)
- `prefers-reduced-motion` nativo no CSS
- Stagger nos filhos via `animation-delay` CSS var

```tsx
import { useEffect, useRef, useState } from "react";

/* ─── hook minimalista ─────────────────────────────────── */
function useInView(options?: IntersectionObserverInit) {
  const ref = useRef<HTMLElement>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) {
        setInView(true);
        observer.disconnect(); // once only
      }
    }, { threshold: 0.15, ...options });

    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return { ref, inView };
}

/* ─── tipos ────────────────────────────────────────────── */
type Direction = "up" | "down" | "left" | "right";

interface AnimateInProps {
  children: React.ReactNode;
  delay?: number;          // ms
  direction?: Direction;
  className?: string;
}

/* ─── componente wrapper ───────────────────────────────── */
function AnimateIn({
  children,
  delay = 0,
  direction = "up",
  className = "",
}: AnimateInProps) {
  const { ref, inView } = useInView();

  const translateMap: Record<Direction, string> = {
    up:    "0, 24px",
    down:  "0, -24px",
    left:  "24px, 0",
    right: "-24px, 0",
  };

  return (
    <div
      ref={ref as React.RefObject<HTMLDivElement>}
      className={className}
      style={{
        "--tx": translateMap[direction],
        "--delay": `${delay}ms`,
        animation: inView
          ? "hero-enter var(--duration, 700ms) var(--ease) var(--delay) both"
          : "none",
        opacity: inView ? undefined : 0,
      } as React.CSSProperties}
    >
      {children}
    </div>
  );
}

/* ─── hero demo ────────────────────────────────────────── */
export default function Hero() {
  return (
    <>
      <style>{`
        /* easing suave — não linear, não ease-in-out genérico */
        :root {
          --ease: cubic-bezier(0.22, 1, 0.36, 1);
          --duration: 700ms;
        }

        @keyframes hero-enter {
          from {
            opacity: 0;
            transform: translate(var(--tx, 0, 24px));
          }
          to {
            opacity: 1;
            transform: translate(0, 0);
          }
        }

        /* respeita preferência do utilizador — não negociável */
        @media (prefers-reduced-motion: reduce) {
          @keyframes hero-enter {
            from { opacity: 0; }
            to   { opacity: 1; }
          }
          :root { --duration: 200ms; }
        }
      `}</style>

      {/* spacer para forçar scroll no demo */}
      <div style={{ height: "30vh", background: "#0f0f0f", display: "grid", placeItems: "center" }}>
        <p style={{ color: "#555", fontFamily: "sans-serif", fontSize: 14 }}>
          ↓ scroll para ver a animação
        </p>
      </div>

      <section
        style={{
          minHeight: "100vh",
          background: "linear-gradient(135deg, #0f0f0f 0%, #1a1a2e 50%, #16213e 100%)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          padding: "4rem 2rem",
          gap: "1.5rem",
        }}
      >
        {/* badge — entra primeiro */}
        <AnimateIn delay={0} direction="up">
          <span style={{
            display: "inline-flex",
            alignItems: "center",
            gap: "0.5rem",
            padding: "0.35rem 1rem",
            borderRadius: "999px",
            border: "1px solid rgba(99,102,241,0.4)",
            background: "rgba(99,102,241,0.1)",
            color: "#a5b4fc",
            fontSize: "0.8rem",
