            letterSpacing: "0.05em",
            textTransform: "uppercase",
          }}>
            <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#818cf8", display: "inline-block" }} />
            Novo produto
          </span>
        </AnimateIn>

        {/* headline — stagger 120ms */}
