## 3. Caso Avançado: Lógica por Região/Cidade

```typescript
// lib/geo-router.ts
export interface GeoContext {
  country: string | null;
  region: string | null;
  city: string | null;
}

export interface RouteDecision {
  path: string;
  reason: string;
}

// Regras hierárquicas: cidade > região > país > default
export function resolveRoute(geo: GeoContext): RouteDecision {
  const { country, region, city } = geo;

  // Regras por cidade (ex: eventos locais, data centers)
  if (country === "US" && city === "New York") {
    return { path: "/en-us/nyc", reason: "city-match" };
  }

  // Regras por região (ex: Quebec → francês)
  if (country === "CA" && region === "QC") {
    return { path: "/fr-ca", reason: "region-match" };
  }
  if (country === "CA") {
    return { path: "/en-ca", reason: "country-match" };
  }

  // Regras por país
  const countryRoutes: Record<string, string> = {
    PT: "/pt",
    BR: "/br",
    US: "/en-us",
    GB: "/en-gb",
  };

  if (country && countryRoutes[country]) {
    return { path: countryRoutes[country], reason: "country-match" };
  }

  return { path: "/en", reason: "fallback" };
}
```

```typescript
// middleware.ts (versão com lib)
import { resolveRoute } from "./lib/geo-router";

export function middleware(request: NextRequest) {
  // ... bypass checks ...

  const geo: GeoContext = {
    country: request.geo?.country ?? null,
    region: request.geo?.region ?? null,
    city: request.geo?.city ?? null,
  };

  const { path, reason } = resolveRoute(geo);

  const response = NextResponse.redirect(
    new URL(path, request.url),
    { status: 307 }
  );

  // Headers de debug (remover em produção ou colocar atrás de flag)
  if (process.env.NODE_ENV !== "production") {
    response.headers.set("x-geo-redirect-reason", reason);
    response.headers.set("x-geo-country", geo.country ?? "unknown");
  }

  return response;
}
```

