# Edge Functions no Vercel para Redirects por Geolocalização

## Estrutura do Projeto

```
my-app/
├── middleware.ts          # Edge Middleware (recomendado)
├── app/
│   ├── page.tsx
│   └── [locale]/
│       └── page.tsx
└── vercel.json
```

---

## 1. Middleware (Abordagem Principal)

```typescript
// middleware.ts
import { NextRequest, NextResponse } from 'next/server'

// Mapeamento de países para locales/regiões
const GEO_REDIRECTS: Record<string, string> = {
  PT: '/pt',
  BR: '/br',
  US: '/en',
  GB: '/en-gb',
  ES: '/es',
  FR: '/fr',
  DE: '/de',
  IT: '/it',
  JP: '/ja',
  CN: '/zh',
}

// Países que redirecionam para página de restrição
const BLOCKED_COUNTRIES = ['KP', 'IR', 'CU']

// Locale padrão
const DEFAULT_LOCALE = '/en'

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl

  // Ignorar assets estáticos e API routes
  if (shouldSkip(pathname)) {
    return NextResponse.next()
  }

  // Verificar se já tem locale na URL (evitar loop)
  if (hasLocalePrefix(pathname)) {
    return NextResponse.next()
  }

  // Obter dados de geolocalização do Vercel
  const country  = request.geo?.country  ?? 'US'
  const region   = request.geo?.region   ?? ''
  const city     = request.geo?.city     ?? ''
  const latitude = request.geo?.latitude ?? ''
  const longitude = request.geo?.longitude ?? ''

  console.log(`[GEO] Country: ${country} | Region: ${region} | City: ${city}`)

  // Verificar países bloqueados
  if (BLOCKED_COUNTRIES.includes(country)) {
    return NextResponse.redirect(new URL('/restricted', request.url))
  }

  // Lógica especial para regiões específicas
  const regionRedirect = getRegionRedirect(country, region, request)
  if (regionRedirect) return regionRedirect

  // Redirect baseado no país
  const locale = GEO_REDIRECTS[country] ?? DEFAULT_LOCALE
  const redirectUrl = new URL(locale + pathname, request.url)

  // Preservar query params
  redirectUrl.search = request.nextUrl.search

  const response = NextResponse.redirect(redirectUrl, {
    status: 307, // Temporary Redirect
  })

  // Guardar geo info em cookies para uso no cliente
  response.cookies.set('user-country', country, {
    maxAge: 60 * 60 * 24, // 24 horas
    path: '/',
    sameSite: 'lax',
  })

  response.cookies.set('user-region', region, {
    maxAge: 60 * 60 * 24,
    path: '/',
    sameSite: 'lax',
  })

  return response
}

// Redirect especial por região/estado
function getRegionRedirect(
  country: string,
  region: string,
  request: NextRequest
): NextResponse | null {
  // Exemplo: Quebec (Canada) → versão francesa
  if (country === 'CA' && region === 'QC') {
    return NextResponse.redirect(new URL('/fr-ca', request.url))
  }

  // Exemplo: Catalunha (Espanha) → versão catalã
  if (country === 'ES' && region === 'CT') {
    return NextResponse.redirect(new URL('/ca', request.url))
  }

  return null
}

// Verificar se a rota deve ser ignorada
function shouldSkip(pathname: string): boolean {
  const skipPatterns = [
    /^\/_next/,
    /^\/api/,
    /^\/static/,
    /\.(.*)$/,          // ficheiros com extensão
    /^\/favicon/,
    /^\/robots/,
    /^\/sitemap/,
  ]

  return skipPatterns.some(pattern => pattern.test(pathname))
}

// Verificar se já tem prefixo de locale
function hasLocalePrefix(pathname: string): boolean {
  const locales = ['pt', 'br', 'en', 'en-gb', 'es', 'fr', 'de', 'it', 'ja', 'zh', 'fr-ca', 'ca']
  return locales.some(locale => 
    pathname.startsWith(`/${locale}/`) || pathname === `/${locale}`
  )
}

// Configurar quais rotas passam pelo middleware
export const config = {
  matcher: [
    /*
     * Executar em todas as rotas EXCETO:
     * - _next/static
     * - _next/image
     * - favicon.ico
     */
    '/((?!_next/static|_next/image|favicon.ico).*)',
  ],
}
```

