## 3. Redirect Condicional Avançado

```typescript
// middleware.ts - versão avançada com preferências do utilizador
import { NextRequest, NextResponse } from 'next/server'

interface GeoConfig {
  locale: string
  currency: string
  timezone: string
}

const COUNTRY_CONFIG: Record<string, GeoConfig> = {
  PT: { locale: 'pt-PT', currency: 'EUR', timezone: 'Europe/Lisbon'   },
  BR: { locale: 'pt-BR', currency: 'BRL', timezone: 'America/Sao_Paulo' },
  US: { locale: 'en-US', currency: 'USD', timezone: 'America/New_York' },
  GB: { locale: 'en-GB', currency: 'GBP', timezone: 'Europe/London'   },
  ES: { locale: 'es-ES', currency: 'EUR', timezone: 'Europe/Madrid'   },
  JP: { locale: 'ja-JP', currency: 'JPY', timezone: 'Asia/Tokyo'      },
}

const DEFAULT_CONFIG: GeoConfig = {
  locale: 'en-US',
  currency: 'USD',
  timezone: 'UTC',
}

export function middleware(request: NextRequest) {
  const { pathname, searchParams } = request.nextUrl

  if (shouldSkip(pathname)) {
    return NextResponse.next()
  }

  const country = request.geo?.country ?? 'US'

  // 1. Verificar preferência guardada em cookie
  const savedLocale = request.cookies.get('preferred-locale')?.value
  if (savedLocale) {
    return handleWithSavedPreference(request, savedLocale)
  }

  // 2. Verificar parâmetro manual na URL (?locale=pt)
  const urlLocale = searchParams.get('locale')
  if (urlLocale) {
    return handleLocaleChange(request, urlLocale)
  }

  // 3. Usar geolocalização
  const config = COUNTRY_CONFIG[country] ?? DEFAULT_CONFIG
  return handleGeoRedirect(request, country, config)
}

function handleGeoRedirect(
  request: NextRequest,
  country: string,
  config: GeoConfig
): NextResponse {
  const { pathname } = request.nextUrl
  const localePath = `/${config.locale.toLowerCase()}`

  if (pathname.startsWith(localePath)) {
    return NextResponse.next()
  }

  const url = new URL(`${localePath}${pathname}`, request.url)
  url.search = request.nextUrl.search

  const response = NextResponse.redirect(url, { status: 307 })

  // Definir cookies com configurações regionais
  const cookieOptions = {
    maxAge: 60 * 60 * 24 * 30, // 30 dias
    path: '/',
    sameSite: 'lax' as const,
    secure: process.env.NODE_ENV === 'production',
  }

  response.cookies.set('user-country',  country,          cookieOptions)
  response.cookies.set('user-locale',   config.locale,    cookieOptions)
  response.cookies.set('user-currency', config.currency,  cookieOptions)
  response.cookies.set('user-timezone', config.timezone,  cookieOptions)

  return response
}

function handleWithSavedPreference(
  request: NextRequest,
  locale: string
): NextResponse {
  const { pathname } = request.nextUrl
  const localePath = `/${locale.toLowerCase()}`

  if (pathname.startsWith(localePath)) {
    return NextResponse.next()
  }

  const url = new URL(`${localePath}${pathname}`, request.url)
  return NextResponse.redirect(url, { status: 307 })
}

function handleLocaleChange(
  request: NextRequest,
  locale: string
): NextResponse {
  const url = new URL(`/${locale}`, request.url)
  const response = NextResponse.redirect(url, { status: 307 })

  response.cookies.set('preferred-locale', locale, {
    maxAge: 60 * 60 * 24 * 365, // 1 ano
    path: '/',
    sameSite: 'lax',
  })

  return response
}

function shouldSkip(pathname: string): boolean {
  return (
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api')   ||
    pathname.includes('.')
  )
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
}
```

