## 4. Componente para Usar os Dados de Geo

```typescript
// hooks/useGeoData.ts
'use client'

import { useEffect, useState } from 'react'

interface GeoData {
  country: string
  region: string
  city: string
  locale: string
  currency: string
  timezone: string
}

export function useGeoData(): GeoData {
  const [geoData, setGeoData] = useState<GeoData>({
    country:  '',
    region:   '',
    city:     '',
    locale:   'en-US',
    currency: 'USD',
    timezone: 'UTC',
  })

  useEffect(() => {
    // Ler cookies definidos pelo middleware
    const cookies = document.cookie.split(';').reduce((acc, cookie) => {
      const [key, value] = cookie.trim().split('=')
      acc[key] = decodeURIComponent(value)
      return acc
    }, {} as Record<string, string>)

    setGeoData({
      country:  cookies['user-country']  ?? '',
      region:   cookies['user-region']   ?? '',
      city:     cookies['user-city']     ?? '',
      locale:   cookies['user-locale']   ?? 'en-US',
      currency: cookies['user-currency'] ?? 'USD',
      timezone: cookies['user-timezone'] ?? 'UTC',
    })
  }, [])

  return geoData
}
