## Opção 2: Redirect por Cookie + Header

Versão mais robusta que respeita preferência do utilizador:

```typescript
import { NextRequest, NextResponse } from 'next/server';
import { geolocation } from '@vercel/functions';

export const config = {
  matcher: ['/((?!api|_next|favicon.ico|.*\\..*).*)'],
};

const COUNTRY_TO_LOCALE: Record<string, string> = {
  PT: 'pt', BR: 'pt-br', US: 'en', ES: 'es',
};

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // Se já tem locale no path, segue normal
  if (/^\/(pt|pt-br|en|es)(\/|$)/.test(pathname)) {
    return NextResponse.next();
  }

  // Respeita preferência guardada
  const savedLocale = request.cookies.get('NEXT_LOCALE')?.value;

  // Senão usa geolocalização
  const { country } = geolocation(request);
  const locale = savedLocale ?? COUNTRY_TO_LOCALE[country ?? ''] ?? 'en';

  const url = request.nextUrl.clone();
  url.pathname = `/${locale}${pathname}`;

  const response = NextResponse.redirect(url);
  response.cookies.set('NEXT_LOCALE', locale, {
    path: '/',
    maxAge: 60 * 60 * 24 * 365, // 1 ano
  });

  return response;
}
```

