    --color-head: #7c6dfa;
    --duration: 0.8s;

    width: var(--size);
    height: var(--size);
    border-radius: 50%;
    border: var(--stroke) solid var(--color-track);
    border-top-color: var(--color-head);

    animation: spin var(--duration) linear infinite;

    /* GPU composite layer — sem layout thrashing */
    will-change: transform;
  }

  /* ── Reduced motion ── */
  @media (prefers-reduced-motion: reduce) {
    .spinner {
      animation-duration: 4s; /* mais lento, não parado */
