# Parallax Performático com Transform/Opacity

## Princípios

```
❌ Evitar: top, left, margin, height, width → layout thrashing
✅ Usar: transform: translateY() + opacity → só composite layer
```

---

## Implementação

### `hooks/useParallax.ts`

```typescript
import { useEffect, useRef, useCallback } from 'react'

interface ParallaxLayer {
  element: HTMLElement
  speed: number        // 0 = fixo, 1 = scroll normal, 0.5 = metade
  direction?: 'up' | 'down'
  fadeOut?: boolean    // opacity diminui ao scrollar
}

export function useParallax() {
  const layers = useRef<ParallaxLayer[]>([])
  const rafId = useRef<number>(0)
  const lastScrollY = useRef(0)
  const ticking = useRef(false)

  const updateLayers = useCallback(() => {
    const scrollY = lastScrollY.current

    layers.current.forEach(({ element, speed, direction, fadeOut }) => {
      const multiplier = direction === 'down' ? speed : -speed
      const translateY = scrollY * multiplier

      // Só transform e opacity — zero layout thrashing
      let transform = `translateY(${translateY}px)`

      // GPU hint: adiciona translateZ(0) para forçar composite layer
      transform += ' translateZ(0)'

      element.style.transform = transform
      element.style.willChange = 'transform'

      if (fadeOut) {
        // Fade baseado na posição do elemento na viewport
        const rect = element.getBoundingClientRect()
        const viewportHeight = window.innerHeight
        const opacity = Math.max(0, 1 - (scrollY / (viewportHeight * 0.8)))
        element.style.opacity = String(opacity)
      }
    })

    ticking.current = false
  }, [])

  const onScroll = useCallback(() => {
    lastScrollY.current = window.scrollY

    // rAF batching — evita múltiplos repaints por frame
    if (!ticking.current) {
      rafId.current = requestAnimationFrame(updateLayers)
      ticking.current = true
    }
  }, [updateLayers])

  const register = useCallback((
    element: HTMLElement | null,
    speed: number,
    options?: Omit<ParallaxLayer, 'element' | 'speed'>
  ) => {
    if (!element) return

    layers.current.push({ element, speed, ...options })
  }, [])

  const unregister = useCallback((element: HTMLElement | null) => {
    if (!element) return
    layers.current = layers.current.filter(l => l.element !== element)
  }, [])

  useEffect(() => {
    window.addEventListener('scroll', onScroll, { passive: true })

    return () => {
      window.removeEventListener('scroll', onScroll)
      cancelAnimationFrame(rafId.current)
    }
  }, [onScroll])

  return { register, unregister }
}
```

