### `components/ParallaxProvider.tsx`

```typescript
import { createContext, useContext, ReactNode } from 'react'
import { useParallax } from '@/hooks/useParallax'

type ParallaxContextType = ReturnType<typeof useParallax>

const ParallaxContext = createContext<ParallaxContextType | null>(null)

export function ParallaxProvider({ children }: { children: ReactNode }) {
  const parallax = useParallax()

  return (
    <ParallaxContext.Provider value={parallax}>
      {children}
    </ParallaxContext.Provider>
  )
}

export function useParallaxContext() {
  const ctx = useContext(ParallaxContext)
  if (!ctx) throw new Error('useParallaxContext fora do ParallaxProvider')
  return ctx
}
