### `components/ParallaxLayer.tsx`

```typescript
'use client'

import { useEffect, useRef, HTMLAttributes } from 'react'
import { useParallaxContext } from './ParallaxProvider'

interface ParallaxLayerProps extends HTMLAttributes<HTMLDivElement> {
  speed?: number          // 0.1 a 0.9 recomendado
  direction?: 'up' | 'down'
  fadeOut?: boolean
  as?: keyof JSX.IntrinsicElements
}

export function ParallaxLayer({
  speed = 0.3,
  direction = 'up',
  fadeOut = false,
  children,
  style,
  ...props
}: ParallaxLayerProps) {
  const ref = useRef<HTMLDivElement>(null)
  const { register, unregister } = useParallaxContext()

  useEffect(() => {
    register(ref.current, speed, { direction, fadeOut })
    return () => unregister(ref.current)
  }, [register, unregister, speed, direction, fadeOut])

  return (
    <div
      ref={ref}
      style={{
        // will-change reserva composite layer desde o início
        willChange: 'transform',
        ...style,
      }}
      {...props}
    >
      {children}
    </div>
  )
}
