        {/* Texto — sobe mais rápido e some */}
        <ParallaxLayer
          speed={0.5}
          direction="up"
          fadeOut
          style={{
            position: 'relative',
            zIndex: 2,
            textAlign: 'center',
          }}
        >
          <h1 style={{ fontSize: 'clamp(2rem, 8vw, 6rem)', color: '#fff' }}>
            Título Principal
          </h1>
          <p style={{ color: '#ccc', fontSize: '1.25rem' }}>
            Subtítulo com parallax suave
          </p>
        </ParallaxLayer>
      </section>

      {/* Resto da página */}
      <section style={{ minHeight: '100vh', padding: '4rem' }}>
        <p>Conteúdo normal abaixo do hero</p>
      </section>
    </ParallaxProvider>
  )
}
