## Dashboard Grid com Tilt 3D (bônus)

```tsx
// DashboardCard3D.tsx — versão com perspectiva no mouse
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import { useRef, MouseEvent } from "react";

const SPRING_CONFIG = { stiffness: 300, damping: 30, mass: 0.5 };

export function DashboardCard3D({ title, value, icon, color = "#6366f1" }) {
  const ref = useRef<HTMLDivElement>(null);

  // Motion values para tilt
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  // Spring suaviza o movimento do mouse
  const springX = useSpring(mouseX, SPRING_CONFIG);
  const springY = useSpring(mouseY, SPRING_CONFIG);

  // Transforma posição do mouse em graus de rotação
  const rotateX = useTransform(springY, [-0.5, 0.5], ["8deg", "-8deg"]);
  const rotateY = useTransform(springX, [-0.5, 0.5], ["-8deg", "8deg"]);

  // Brilho segue o mouse
  const glareX = useTransform(springX, [-0.5, 0.5], ["0%", "100%"]);
  const glareY = useTransform(springY, [-0.5, 0.5], ["0%", "100%"]);

  function handleMouseMove(e: MouseEvent<HTMLDivElement>) {
    if (!ref.current) return;
    const { left, top, width, height } = ref.current.getBoundingClientRect();

    // Normaliza entre -0.5 e 0.5
    mouseX.set((e.clientX - left) / width - 0.5);
    mouseY.set((e.clientY - top) / height - 0.5);
  }

  function handleMouseLeave() {
    mouseX.set(0);
    mouseY.set(0);
  }

  return (
    <div style={{ perspective: "1000px" }}>
      <motion.div
        ref={ref}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        style={{
          rotateX,
