## JavaScript — `animation.js`

```js
/**
 * STAGGER SEQUENCE — ScrollTrigger Scrub
 * ─────────────────────────────────────────────────────────────
 * Arquitectura:
 *  1. CONFIG  — dados por elemento (ease, from, duração relativa)
 *  2. SETUP   — gsap.set() define estado inicial
 *  3. TIMELINE — master tl com posições absolutas (não stagger nativo)
 *               → permite easing DIFERENTE por elemento
 *  4. SCROLLTRIGGER — pin + scrub liga scroll à timeline
 *  5. DEBUG   — barra de progresso em tempo real
 */

gsap.registerPlugin(ScrollTrigger);

/* ─── 1. CONFIG ─────────────────────────────────────────────── */

const ITEMS_CONFIG = [
  {
    ease:     "power4.out",
    duration: 0.6,
    from:     { x: -80, opacity: 0, scale: 0.9 },
    stagger:  0.0,   // posição de entrada na timeline (0–1 normalizado)
  },
  {
    ease:     "elastic.out(1, 0.5)",
    duration: 0.9,   // elastic precisa de mais "espaço"
    from:     { x: 80, opacity: 0, scale: 0.85 },
    stagger:  0.12,
  },
  {
    ease:     "back.out(2.5)",
    duration: 0.65,
    from:     { y: 60, opacity: 0, rotation: -8 },
    stagger:  0.22,
  },
  {
    ease:     "circ.out",
    duration: 0.55,
    from:     { x: -60, opacity: 0, skewX: 12 },
    stagger:  0.32,
  },
  {
    ease:     "expo.out",
    duration: 0.7,
    from:     { y: -50, opacity: 0, scale: 1.1 },
    stagger:  0.42,
  },
  {
    ease:     "bounce.out",
    duration: 0.85,
    from:     { y: 80, opacity: 0 },
    stagger:  0.52,
  },
];

/* ─── 2. SETUP ──────────────────────────────────────────────── */

const items = gsap.utils.toArray(".seq-item");

// Define estado inicial de cada elemento
items.forEach((el, i) => {
  gsap.set(el, ITEMS_CONFIG[i].from);
});

/* ─── 3. MASTER TIMELINE ────────────────────────────────────── */

/**
 * totalDuration: duração "virtual" da timeline.
 * Cada tween é inserido em posição absoluta (stagger * totalDuration).
 * Isto dá controlo total sobre sobreposição e sequência.
 */
const TOTAL_DURATION = 3; // segundos virtuais (o scroll mapeia para isto)

const masterTl = gsap.timeline({ paused: true });

items.forEach((el, i) => {
  const cfg = ITEMS_CONFIG[i];

  // Posição absoluta na timeline
  const insertAt = cfg.stagger * TOTAL_DURATION;

  masterTl.to(
    el,
    {
      // "to" — anima DE from (já definido via gsap.set) PARA estado natural
      x:        0,
      y:        0,
      opacity:  1,
      scale:    1,
      rotation: 0,
      skewX:    0,
      duration: cfg.duration,
      ease:     cfg.ease,
    },
    insertAt  // ← posição absoluta, não relativa
  );
});

/* ─── 4. SCROLLTRIGGER ──────────────────────────────────────── */

ScrollTrigger.create({
  trigger:  "#stage",
  start:    "top top",
  end:      "+=250%",      // pin window = 2.5× viewport height
  pin:      true,
  scrub:    1.2,           // lag suave (segundos de smoothing)
  animation: masterTl,

  // Callbacks de estado
  onEnter:      () => debugSetActive(true),
  onLeave:      () => debugSetActive(false),
  onEnterBack:  () => debugSetActive(true),
  onLeaveBack:  () => debugSetActive(false),

  onUpdate: (self) => {
    updateDebug(self.progress);
  },
});

/* ─── 5. DEBUG ──────────────────────────────────────────────── */

const debugEl   = document.getElementById("scrubDebug");
const fillEl    = document.getElementById("scrubFill");
const labelEl   = document.getElementById("scrubLabel");

function debugSetActive(state) {
  debugEl.classList.toggle("is-active", state);
}

function updateDebug(progress) {
  const pct = Math.round(progress * 100);
  fillEl.style.width  = `${pct}%`;
  labelEl.textContent = `${pct}%`;
}

/* ─── 6. RESIZE HANDLER ─────────────────────────────────────── */

// ScrollTrigger recalcula automaticamente,
// mas forçamos refresh em resize para evitar drift
let resizeTimer;
window.addEventListener("resize", () => {
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(() => ScrollTrigger.refresh(), 200);
});
```

