## 4. Variante zero-dependência

Para quando o GSAP é demasiado:

```js
const items = [...document.querySelectorAll(".item")];
const scene = document.querySelector(".scene");

// easings: t ∈ [0,1] → [0,1]
const easings = [
  t => 1 - Math.pow(1 - t, 2),                       // power2.out
  t => 1 + 2.7 * Math.pow(t - 1, 3) + 1.7 * Math.pow(t - 1, 2), // back.out
  t => t === 1 ? 1 : 1 - Math.pow(2, -10 * t),       // expo.out
  t => {                                              // elastic.out
    const c4 = (2 * Math.PI) / 3;
    return t === 0 ? 0 : t === 1 ? 1
      : Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * c4) + 1;
  },
  t => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2, // power3.inOut
  t => Math.sqrt(1 - Math.pow(t - 1, 2)),            // circ.out
];

const STAGGER = 0.08, DURATION = 0.4;
const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const remap = (v, a, b) => clamp((v - a) / (b - a));

let progress = 0, target = 0;

function onScroll() {
  const rect = scene.getBoundingClientRect();
  const total = rect.height - window.innerHeight;
  target = clamp(-rect.top / total);
}

function tick() {
  progress += (target - progress) * 0.1;             // smoothing
  items.forEach((el, i) => {
    const start = i * STAGGER;
    const local = remap(progress, start, start + DURATION);
    const e = easings[i](local);
    el.style.opacity = e;
    el.style.transform = `translate3d(0, ${(1 - e) * 60}px, 0) scale(${0.9 + 0.1 * e})`;
  });
  requestAnimationFrame(tick);
}

addEventListener("scroll", onScroll, { passive: true });
onScroll(); tick();
```

