## 💻 Implementação: Server Side

### 1. Endpoint de Login

```typescript
// auth.controller.ts
import { createHash, randomBytes } from 'crypto';
import { SignJWT } from 'jose';

interface RefreshTokenRecord {
  tokenHash:  string;
  familyId:   string;  // para detecção de reuse
  userId:     string;
  usedAt:     Date | null;
  expiresAt:  Date;
  ipHint:     string;
  userAgent:  string;
}

class AuthController {

  async login(req: Request, res: Response) {
    const { email, password } = req.body;

    // 1. Validar credenciais
    const user = await this.userService.validateCredentials(email, password);
    if (!user) {
      // Timing-safe: espera sempre o mesmo tempo para não revelar se email existe
      await this.timingSafeDelay(200);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // 2. Gerar Access Token (curta duração, stateless)
    const accessToken = await this.generateAccessToken(user);

    // 3. Gerar Refresh Token (longa duração, stateful)
    const { rawToken, record } = await this.generateRefreshToken(user, req);

    // 4. Persistir refresh token (hash, nunca o valor raw)
    await this.tokenStore.save(record);

    // 5. Access token vai no body (será guardado em memória pelo cliente)
    // 6. Refresh token vai em cookie HttpOnly
    res
      .cookie('__Host-refresh_token', rawToken, {
        httpOnly:  true,
        secure:    true,           // HTTPS obrigatório
        sameSite:  'strict',
        path:      '/auth',        // Só enviado para /auth/*
        maxAge:    7 * 24 * 60 * 60 * 1000,  // 7 dias
        // __Host- prefix: garante Secure + sem Domain + Path=/
      })
      .json({
        accessToken,
        expiresIn: 900,  // 15 minutos em segundos
        tokenType: 'Bearer',
      });
  }

  private async generateAccessToken(user: User): Promise<string> {
    const secret = new TextEncoder().encode(process.env.JWT_SECRET);

    return new SignJWT({
      sub:   user.id,
      email: user.email,
      roles: user.roles,
      // NÃO incluir dados sensíveis: passwords, PII desnecessária
    })
      .setProtectedHeader({ alg: 'HS256' })
      .setIssuedAt()
      .setExpirationTime('15m')   // Curto! 
      .setJti(randomBytes(16).toString('hex'))  // JWT ID único
      .sign(secret);
  }

  private async generateRefreshToken(
    user: User, 
    req: Request
  ): Promise<{ rawToken: string; record: RefreshTokenRecord }> {

    const rawToken  = randomBytes(64).toString('base64url');
    const tokenHash = createHash('sha256').update(rawToken).digest('hex');
    const familyId  = randomBytes(16).toString('hex');

    const record: RefreshTokenRecord = {
      tokenHash,
      familyId,
      userId:    user.id,
      usedAt:    null,
      expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
      ipHint:    req.ip,
      userAgent: req.headers['user-agent'] ?? '',
    };

    return { rawToken, record };
  }
}
```

