### 2. Endpoint de Refresh com Rotation + Detecção de Reuse

```typescript
async refresh(req: Request, res: Response) {
  const rawToken = req.cookies['__Host-refresh_token'];

  if (!rawToken) {
    return res.status(401).json({ error: 'No refresh token' });
  }

  const tokenHash = createHash('sha256').update(rawToken).digest('hex');

  // Buscar token na DB
  const record = await this.tokenStore.findByHash(tokenHash);

  // ════════════════════════════════════════════
  // DETECÇÃO DE REUSE: O cenário mais crítico
  // ════════════════════════════════════════════
  if (!record) {
    // Token não existe na DB
    // PODE SER: token já usado (rotation) → possível ataque!

    // Verificar se pertence a uma família conhecida
    // (isto requer guardar tokens usados por um período)
    const orphanFamily = await this.tokenStore.findFamilyByHash(tokenHash);

    if (orphanFamily) {
      // Token desta família foi usado antes → ATAQUE DETECTADO
      // Invalidar TODA a família (todos os tokens activos do utilizador)
      await this.tokenStore.revokeFamily(orphanFamily.familyId);

      // Notificar utilizador
      await this.notificationService.sendSecurityAlert(
        orphanFamily.userId,
        'Suspicious login activity detected. All sessions terminated.'
      );

      this.logger.security('REFRESH_TOKEN_REUSE_DETECTED', {
        familyId: orphanFamily.familyId,
        ip: req.ip,
        userAgent: req.headers['user-agent'],
      });
    }

    // Limpar cookie
    res.clearCookie('__Host-refresh_token', { path: '/auth' });
    return res.status(401).json({ error: 'Invalid refresh token' });
  }

  // Verificar expiração
  if (record.expiresAt < new Date()) {
    await this.tokenStore.delete(record.tokenHash);
    res.clearCookie('__Host-refresh_token', { path: '/auth' });
    return res.status(401).json({ error: 'Refresh token expired' });
  }

  // ════════════════════════════════════════════
  // ROTATION: Invalidar token actual, emitir novo
  // ════════════════════════════════════════════

  // Marcar como usado (para detecção de reuse posterior)
  await this.tokenStore.markAsUsed(record.tokenHash);

  // Gerar novo par de tokens
  const user = await this.userService.findById(record.userId);
  const newAccessToken = await this.generateAccessToken(user);
  const { rawToken: newRawToken, record: newRecord } = 
    await this.generateRefreshToken(user, req);

  // Manter o mesmo familyId para rastreamento
  newRecord.familyId = record.familyId;

  // Persistir novo refresh token
  await this.tokenStore.save(newRecord);

  res
    .cookie('__Host-refresh_token', newRawToken, {
      httpOnly: true,
      secure:   true,
      sameSite: 'strict',
      path:     '/auth',
      maxAge:   7 * 24 * 60 * 60 * 1000,
    })
    .json({
      accessToken: newAccessToken,
      expiresIn:   900,
    });
}
```

