## 1. EASING — Problemas Comuns

### ❌ Padrão Problemático

```javascript
// ERRADO — easing linear sem lerp, movimento robótico
window.addEventListener('scroll', () => {
  const offset = window.scrollY;
  element.style.transform = `translateY(${offset * 0.5}px)`;
});

// ERRADO — easing CSS em propriedade que muda a cada frame
element.style.transition = 'transform 0.3s ease-out'; // jank garantido
element.style.transform = `translateY(${offset}px)`;
```

### ✅ Padrão Correto

```javascript
// CORRETO — lerp manual para suavização real
class ParallaxController {
  #current = 0;
  #target  = 0;
  #ease    = 0.08;   // 0.05–0.12 é o sweet spot
  #raf     = null;
  #isRunning = false;

  constructor(element, factor = 0.4) {
    this.el     = element;
    this.factor = Math.max(0, Math.min(1, factor)); // clamp seguro
  }

  #lerp(a, b, t) {
    return a + (b - a) * t;
  }

  #tick = () => {
    this.#current = this.#lerp(this.#current, this.#target, this.#ease);

    // Para o loop quando está suficientemente próximo
    if (Math.abs(this.#target - this.#current) < 0.05) {
      this.#current   = this.#target;
      this.#isRunning = false;
      return; // sem cancelar o raf explicitamente — simplesmente não reagenda
    }

    this.el.style.transform = `translateY(${this.#current}px)`;
    this.#raf = requestAnimationFrame(this.#tick);
  };

  update(scrollY) {
    this.#target = scrollY * this.factor;

    if (!this.#isRunning) {
      this.#isRunning = true;
      this.#raf = requestAnimationFrame(this.#tick);
    }
  }

  destroy() {
    if (this.#raf) cancelAnimationFrame(this.#raf);
  }
}
```

