## 2. PERFORMANCE — Problemas Comuns

### ❌ Anti-patterns Críticos

```javascript
// PROBLEMA 1 — Leitura de layout dentro do scroll handler (forced reflow)
window.addEventListener('scroll', () => {
  const rect = element.getBoundingClientRect(); // ← lê layout → força reflow
  const height = element.offsetHeight;          // ← idem
  element.style.transform = `translateY(${rect.top * 0.5}px)`;
});

// PROBLEMA 2 — Sem throttle/rAF no scroll
window.addEventListener('scroll', heavyCalculation); // dispara 60x/s ou mais

// PROBLEMA 3 — Múltiplos elementos sem batch
elements.forEach(el => {
  window.addEventListener('scroll', () => { // N listeners!
    el.style.top = ...; // ← top/left causam layout, não usar
  });
});

// PROBLEMA 4 — will-change em tudo
// Consome memória de GPU por cada elemento promovido
element.style.willChange = 'transform'; // só quando necessário
```

### ✅ Padrão Correto

```javascript
class ParallaxSystem {
  #elements   = new Map();
  #scrollY    = 0;
  #ticking    = false;
  #observer   = null;
  #visible    = new Set();

  constructor() {
    this.#setupScrollListener();
    this.#setupIntersectionObserver();
  }

  // ─── Scroll: apenas agenda, nunca calcula aqui ───────────────────
  #setupScrollListener() {
    // Passive: true — nunca bloqueia o scroll thread
    window.addEventListener('scroll', this.#onScroll, { passive: true });
  }

  #onScroll = () => {
    this.#scrollY = window.scrollY; // leitura barata

    if (!this.#ticking) {
      this.#ticking = true;
      requestAnimationFrame(this.#update);
    }
  };

  // ─── rAF: batch de todas as escritas ─────────────────────────────
  #update = () => {
    // 1. Fase de LEITURA (sem intercalar com escritas)
    const reads = [];
    for (const [el, config] of this.#elements) {
      if (this.#visible.has(el)) {
        reads.push({ el, config });
      }
    }

    // 2. Fase de ESCRITA
    for (const { el, config } of reads) {
      const offset = this.#scrollY * config.factor;
      // transform + opacity: únicas propriedades sem reflow
      el.style.transform = `translateY(${offset}px)`;
    }

    this.#ticking = false;
  };

  // ─── IntersectionObserver: só anima o que está visível ───────────
  #setupIntersectionObserver() {
    this.#observer = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            // Promove para GPU apenas quando visível
            entry.target.style.willChange = 'transform';
            this.#visible.add(entry.target);
          } else {
            // Liberta memória GPU quando sai do viewport
            entry.target.style.willChange = 'auto';
            this.#visible.delete(entry.target);
          }
        });
      },
      { rootMargin: '100px' } // margem de segurança
    );
  }

  add(element, factor = 0.4) {
    // Validação de entrada
    if (!(element instanceof HTMLElement)) {
      throw new TypeError('ParallaxSystem.add: elemento inválido');
    }
    if (typeof factor !== 'number' || !isFinite(factor)) {
      throw new TypeError('ParallaxSystem.add: factor deve ser número finito');
    }

    this.#elements.set(element, { factor: Math.max(-1, Math.min(1, factor)) });
    this.#observer.observe(element);
  }

  // ─── Cleanup obrigatório ──────────────────────────────────────────
  destroy() {
    window.removeEventListener('scroll', this.#onScroll);
    this.#observer.disconnect();
    this.#elements.clear();
    this.#visible.clear();
  }
}
```

