## 3. SEGURANÇA — Vetores de Ataque

### ❌ Vulnerabilidades Comuns

```javascript
// CRÍTICO — XSS via injeção em style
const userFactor = getUserInput();                        // "0.5; color: red"
element.style.cssText = `transform: translateY(${userFactor}px)`; // ← injeção CSS

// CRÍTICO — Prototype pollution via config externa
const config = JSON.parse(externalData);                 // dados não validados
Object.assign(defaultConfig, config);                    // ← pollution

// MÉDIO — ReDoS em parsing de seletores
const selector = userInput;
document.querySelectorAll(selector);                     // ← ReDoS possível

// MÉDIO — Memory leak sem cleanup
class Parallax {
  init() {
    window.addEventListener('scroll', this.handler);     // nunca removido
    this.observer = new IntersectionObserver(...);       // nunca desconectado
  }
  // sem destroy() ← leak garantido em SPAs
}
```

### ✅ Defesas

```javascript
class SecureParallaxSystem {
  // Whitelist de propriedades permitidas
  static #ALLOWED_PROPS = new Set(['factor', 'axis', 'clamp']);

  static #sanitizeConfig(config) {
    if (typeof config !== 'object' || config === null) {
      throw new TypeError('Config deve ser um objeto');
    }

    // Previne prototype pollution
    if (Object.prototype.hasOwnProperty.call(config, '__proto__') ||
        Object.prototype.hasOwnProperty.call(config, 'constructor') ||
        Object.prototype.hasOwnProperty.call(config, 'prototype')) {
      throw new Error('Config contém chaves proibidas');
    }

    const safe = Object.create(null); // sem prototype

    for (const key of SecureParallaxSystem.#ALLOWED_PROPS) {
      if (key in config) {
        safe[key] = config[key];
      }
    }

    return safe;
  }

  static #sanitizeFactor(value) {
    const n = Number(value);

    if (!isFinite(n)) throw new RangeError(`Factor inválido: ${value}`);

    // Clamp: previne valores absurdos que causam layout fora do viewport
    return Math.max(-2, Math.min(2, n));
  }

  // Escrita segura em style — nunca usa cssText com input externo
  static #applyTransform(element, y, x = 0) {
    // Valores numéricos puros — sem interpolação de strings com input externo
    const safeY = Number(y.toFixed(4)); // limita precisão
    const safeX = Number(x.toFixed(4));

    // transform é seguro; cssText não é
    element.style.transform = `translate(${safeX}px, ${safeY}px)`;
  }

  // CSP-friendly: sem eval, sem new Function
  add(element, rawConfig = {}) {
    const config = SecureParallaxSystem.#sanitizeConfig(rawConfig);
    const factor = SecureParallaxSystem.#sanitizeFactor(config.factor ?? 0.4);

    // Verifica que o elemento pertence ao documento atual
    // Previne ataques com elementos de iframes
    if (!document.contains(element)) {
      throw new Error('Elemento não pertence ao documento atual');
    }

    this.#elements.set(element, { factor });
    this.#observer.observe(element);
  }
}
```

