## 4. ACESSIBILIDADE — Frequentemente Esquecida

```javascript
class AccessibleParallaxSystem extends SecureParallaxSystem {
  #prefersReducedMotion = false;
  #motionQuery = null;

  constructor() {
    super();
    this.#setupMotionPreference();
  }

  #setupMotionPreference() {
    this.#motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');

    // Estado inicial
    this.#prefersReducedMotion = this.#motionQuery.matches;

    // Reage a mudanças em tempo real (utilizador muda nas definições do SO)
    this.#motionQuery.addEventListener('change', (e) => {
      this.#prefersReducedMotion = e.matches;

      if (e.matches) {
        // Remove transforms imediatamente
        this.#resetAllTransforms();
      }
    });
  }

  #resetAllTransforms() {
    for (const [el] of this.#elements) {
      el.style.transform = '';
      el.style.willChange = 'auto';
    }
  }

  // Override do update para respeitar preferência
  #update = () => {
    if (this.#prefersReducedMotion) return; // para tudo
    super.#update?.();
  };
}
```

